function hexToRgb(hex) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : null;
}

function getLuminance(rgb) {
  const [r, g, b] = [rgb.r, rgb.g, rgb.b].map(x => {
    x = x / 255;
    return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function getContrast(color1, color2) {
  const l1 = getLuminance(hexToRgb(color1));
  const l2 = getLuminance(hexToRgb(color2));
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

const lightColor = '#0b57d0';
const darkColor = '#5FA3E8';
const lightBg = '#FFFFFF';
const darkBg = '#10141A';

const contrastLight = getContrast(lightColor, lightBg);
const contrastDark = getContrast(darkColor, darkBg);

console.log('A2UI final configuration:');
console.log(`  Light mode color: ${lightColor}`);
console.log(`  Dark mode color: ${darkColor}`);
console.log(`  Contrast vs light background (#FFF): ${contrastLight.toFixed(2)}:1 ${contrastLight >= 3 ? '✓' : '✗'}`);
console.log(`  Contrast vs dark background (#10141A): ${contrastDark.toFixed(2)}:1 ${contrastDark >= 3 ? '✓' : '✗'}`);
EOF
node /tmp/final_contrast_check.js

